/**
 * Where generated bytes live, and how a browser is allowed to ask for them.
 *
 * ============================================================================
 * The rule this module exists to enforce
 * ============================================================================
 *
 * `GeneratedAsset.location` is **a path on this machine**, not a URL. It is
 * produced by whatever `saveBytes` seam was wired in, which today means
 * `GENERATION_OUTPUT_DIR` or the system temp directory, and tomorrow means the
 * VIDEO session's bucket. Handing that string to an `<img src>` does nothing in
 * a browser and something much worse in a route handler that trusts it.
 *
 * So the path is never served. A **name** is served, validated against the
 * shape its own two builders produce, and the path is rebuilt from the
 * configured directory. That is `cutPath()`'s discipline, in its own words:
 *
 * > The summary's `file` is an absolute path produced on this machine, and
 * > serving it verbatim would let whatever wrote it choose any file on disk.
 *
 * Same hazard here, with one extra edge: generation's writer is a *model's*
 * response, one layer further from us than ffmpeg is. `..%2f..%2fetc%2fpasswd`
 * never reaches `path.join`, because it is not sixteen hex digits followed by a
 * beat slug.
 *
 * ============================================================================
 * Why the directory moved here from the adapter
 * ============================================================================
 *
 * `defaultSaveBytes` computed it inline, which was right when exactly one
 * function needed it. The read route needs the same answer, and two
 * implementations of "where did we put it" is how a screen starts 404ing on
 * files that are sitting on disk — a bug with no error attached, which is the
 * kind this codebase keeps having to write down. One definition, imported by
 * both.
 */

import 'server-only'

import os from 'node:os'
import path from 'node:path'

import type { EnvLike } from './types'

/** The variable, named once, so a deploy and a test spell it the same way. */
export const GENERATION_OUTPUT_DIR_VAR = 'GENERATION_OUTPUT_DIR'

/**
 * Where generated media is written, and the default is temp on purpose.
 *
 * `defaultSaveBytes`'s reasoning, kept with the code it belongs to: a default
 * that wrote into the repository would put generated media in somebody's
 * working tree, where it would be committed once and then explained forever —
 * and non-negotiable 1 means the one thing this directory must never
 * accumulate is footage whose provenance nobody can reconstruct.
 */
export function generationOutputDirectory(env: EnvLike = process.env): string {
  return env[GENERATION_OUTPUT_DIR_VAR] ?? path.join(os.tmpdir(), 'mirrorline-ai')
}

/**
 * The only filename shape this product produces, spelled out.
 *
 * Derived from its two builders rather than guessed: `promptRef()` returns
 * `prompt_` and sixteen lowercase hex digits, and the adapter appends
 * `-<beat-slug>` and an extension. So `prompt_6b9f0a2c1d8e4f03-hook.mp4` is
 * servable and nothing else is.
 *
 * Deliberately tighter than "no slashes and no dots". A deny-list of dangerous
 * characters has to be kept complete against every encoding a browser, a proxy
 * and `path.join` disagree about; an allow-list of sixteen hex digits is
 * complete the day it is written. The cost is real and worth naming: a beat
 * label carrying punctuation — `Payoff!` — slugs to a name this refuses, so the
 * asset renders with no preview rather than with a preview of something else.
 * Refusing to serve a file we cannot name with certainty is the right direction
 * for that trade.
 */
const SERVABLE_NAME = /^prompt_[0-9a-f]{16}-[a-z0-9]+(?:-[a-z0-9]+)*\.(?:mp4|jpg)$/

/** The sample adapter's `location`, which is a URI nothing can open. */
const SAMPLE_SCHEME = 'sample://'

export function isServableAssetName(value: string): boolean {
  return SERVABLE_NAME.test(value)
}

/**
 * The servable name inside a `location`, or `null` if there is not one.
 *
 * `null` has three distinct causes and the caller treats them alike, which is
 * fine because the answer is the same: do not offer a preview. They are a
 * `sample://` URI (the canned adapter — there are no bytes), a name that does
 * not match the shape above, and a location that is not a path at all.
 */
export function servableAssetName(location: string): string | null {
  if (location.startsWith(SAMPLE_SCHEME)) return null

  const name = path.basename(location)
  return isServableAssetName(name) ? name : null
}

/**
 * The path a validated name refers to, rebuilt rather than trusted.
 *
 * Throws on a name that did not come from `isServableAssetName`, because the
 * alternative — returning a path built from unvalidated input and letting the
 * caller remember to check — is the shape of every traversal bug ever written.
 * `cutPath` throws for the same reason.
 */
export function generatedAssetPath(name: string, env: EnvLike = process.env): string {
  if (!isServableAssetName(name)) throw new Error('not a generated asset name')

  // Joined from a name that cannot contain a separator, so this cannot leave
  // the directory. The validation above is what makes that sentence true.
  return path.join(generationOutputDirectory(env), name)
}

/** Where the dev screen points a `<video>` or an `<img>`, or `null`. */
export function generatedAssetUrl(location: string): string | null {
  const name = servableAssetName(location)
  return name === null ? null : `/api/generation/asset/${name}`
}

/**
 * What to send it as, from the extension we put there ourselves.
 *
 * Not sniffed from the bytes. The extension is chosen by the adapter from the
 * kind it asked for, so it is ours — and a route that guessed a content type
 * from file contents would be inventing a second opinion about a fact we
 * already hold.
 */
export function assetContentType(name: string): string {
  return name.endsWith('.mp4') ? 'video/mp4' : 'image/jpeg'
}
